export const orderResolver: ResolveFn<Order> = (route) => {
  const orders = inject(OrderService);
  return orders.getById(route.paramMap.get('id')!);
};

export const adminGuard: CanActivateFn = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  return auth.hasRole('admin') || router.createUrlTree(['/login']);
};

export const ORDER_ROUTES: Routes = [
  {
    path: ':id',
    resolve: { order: orderResolver },
    loadComponent: () => import('./order-detail.component').then(m => m.OrderDetailComponent),
  },
  {
    path: ':id/refund',
    canActivate: [adminGuard],
    loadComponent: () => import('./order-refund.component').then(m => m.OrderRefundComponent),
  },
];

